using System.Threading;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

namespace FlashSale.OrderService.Data;

/// <summary>
/// Client-side fallback for <see cref="Entities.OrderStatusHistory.Seq"/>, used
/// only when the context runs against SQLite (the unit tests). SQLite cannot
/// generate a database identity on a non-key column, so this assigns a
/// monotonic insertion-order value instead. Production always runs against
/// PostgreSQL, where Seq is a real <c>GENERATED BY DEFAULT AS IDENTITY</c>
/// column and this generator is never selected
/// (see OrderServiceDbContext.OnModelCreating).
/// </summary>
public class OrderStatusHistorySeqGenerator : ValueGenerator<long>
{
    private static long _next;

    public override bool GeneratesTemporaryValues => false;

    public override long Next(EntityEntry entry) => Interlocked.Increment(ref _next);
}
